哈希表.template:
def two_sum(nums: list[int], target: int) -> list[int]:
    seen = {}
    for index, value in enumerate(nums):
        need = target - value
        if need in seen:
            return [seen[need], index]
        seen[value] = index
    return []

双指针.template:
def max_area(height: list[int]) -> int:
    left = 0
    right = len(height) - 1
    best = 0
    while left < right:
        width = right - left
        area = min(height[left], height[right]) * width
        best = max(best, area)
        if height[left] <= height[right]:
            left += 1
        else:
            right -= 1
    return best

滑动窗口.template:
def length_of_longest_substring(s: str) -> int:
    last = {}
    left = 0
    best = 0
    for right, ch in enumerate(s):
        if ch in last:
            left = max(left, last[ch] + 1)
        last[ch] = right
        best = max(best, right - left + 1)
    return best

子串.template:
def subarray_sum(nums: list[int], k: int) -> int:
    seen = {0: 1}
    prefix = 0
    answer = 0
    for value in nums:
        prefix += value
        answer += seen.get(prefix - k, 0)
        seen[prefix] = seen.get(prefix, 0) + 1
    return answer

矩阵.template:
def spiral(matrix: list[list[int]]) -> list[int]:
    if not matrix or not matrix[0]:
        return []
    rows = len(matrix)
    cols = len(matrix[0])
    top = 0
    bottom = rows - 1
    left = 0
    right = cols - 1
    answer = []
    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            answer.append(matrix[top][col])
        top += 1
        for row in range(top, bottom + 1):
            answer.append(matrix[row][right])
        right -= 1
        if top <= bottom:
            for col in range(right, left - 1, -1):
                answer.append(matrix[bottom][col])
            bottom -= 1
        if left <= right:
            for row in range(bottom, top - 1, -1):
                answer.append(matrix[row][left])
            left += 1
    return answer

二叉树.template:
from __future__ import annotations


def tree_height(root: TreeNode | None) -> int:
    if root is None:
        return 0
    heights = {}
    stack = [(root, False)]
    while stack:
        node, expanded = stack.pop()
        if expanded:
            left_height = 0 if node.left is None else heights[node.left]
            right_height = 0 if node.right is None else heights[node.right]
            heights[node] = 1 + max(left_height, right_height)
            continue
        stack.append((node, True))
        if node.right is not None:
            stack.append((node.right, False))
        if node.left is not None:
            stack.append((node.left, False))
    return heights[root]

图论.template:
from collections import deque


def count_islands(grid: list[list[str]]) -> int:
    if not grid or not grid[0]:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    islands = 0
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))
    for start_row in range(rows):
        for start_col in range(cols):
            if grid[start_row][start_col] != "1":
                continue
            islands += 1
            grid[start_row][start_col] = "0"
            queue = deque([(start_row, start_col)])
            while queue:
                row, col = queue.popleft()
                for dr, dc in directions:
                    next_row = row + dr
                    next_col = col + dc
                    if not (0 <= next_row < rows and 0 <= next_col < cols):
                        continue
                    if grid[next_row][next_col] != "1":
                        continue
                    grid[next_row][next_col] = "0"
                    queue.append((next_row, next_col))
    return islands

二分查找.template:
def lower_bound(nums: list[int], target: int) -> int:
    left = 0
    right = len(nums)
    while left < right:
        middle = (left + right) // 2
        if nums[middle] < target:
            left = middle + 1
        else:
            right = middle
    return left

栈.template:
def daily_temperatures(temperatures: list[int]) -> list[int]:
    answer = [0] * len(temperatures)
    stack = []
    for today, temperature in enumerate(temperatures):
        while stack and temperature > temperatures[stack[-1]]:
            previous = stack.pop()
            answer[previous] = today - previous
        stack.append(today)
    return answer

堆.template:
from collections import Counter
import heapq


def top_k_frequent(nums: list[int], k: int) -> list[int]:
    counts = Counter(nums)
    heap = []
    for value, frequency in counts.items():
        heapq.heappush(heap, (frequency, value))
        if len(heap) > k:
            heapq.heappop(heap)
    answer = [0] * k
    for index in range(k - 1, -1, -1):
        answer[index] = heapq.heappop(heap)[1]
    return answer

动态规划.template:
def can_partition(nums: list[int]) -> bool:
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    reachable = [False] * (target + 1)
    reachable[0] = True
    for value in nums:
        for capacity in range(target, value - 1, -1):
            reachable[capacity] = reachable[capacity] or reachable[capacity - value]
    return reachable[target]

多维动态规划.template:
def min_path_sum(grid: list[list[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])
    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = grid[0][0]
    for col in range(1, cols):
        dp[0][col] = dp[0][col - 1] + grid[0][col]
    for row in range(1, rows):
        dp[row][0] = dp[row - 1][0] + grid[row][0]
    for row in range(1, rows):
        for col in range(1, cols):
            dp[row][col] = grid[row][col] + min(
                dp[row - 1][col], dp[row][col - 1]
            )
    return dp[rows - 1][cols - 1]

