def sort_colors(nums: list[int]) -> None:
    left = 0
    index = 0
    right = len(nums) - 1
    while index <= right:
        if nums[index] == 0:
            nums[left], nums[index] = nums[index], nums[left]
            left += 1
            index += 1
        elif nums[index] == 2:
            nums[index], nums[right] = nums[right], nums[index]
            right -= 1
        else:
            index += 1
